  "viewpoint": {
    "person": "third",
    "character": "瀬川ミナ",
    "aliases": ["ミナ"],
    "pronouns": []
  },
  "narrator": {
    "knows_ja": "瀬川ミナが見たこと、測ったこと、聞いたこと、手に取ったものだけを知る。源治やユウジの内心は、表情・手つき・言いよどみとして外から描く。既に死んでいる瀬川宗一の内心や、ミナのいない場所での会話は語らない。"
  },
  "sample": "六時四十分。一号湯の湯口に温度計を沈め、三十秒待つ。目盛りは四十二度二分。帳面の昨日の欄は四十二度五分だった。ミナは鉛筆を舌先で湿らせ、今日の欄に同じ数字を書く前に、もう一度湯に手を入れた。指先に届く熱が、昨日より薄い。",
  "banned": [
    {"id": "b1", "pattern": "運命", "message_ja": "湯の温度も帳面の数字も人の都合で動く話なので、運命に預けると選択の重みが消える。"},
    {"id": "b2", "pattern": "奇跡", "message_ja": "湯は戻らない。戻らないことを書く話なので、奇跡で回収しない。"},
    {"id": "b3", "pattern": "涙が", "message_ja": "感情は数字と手つきに預ける。涙で処理すると、帳面の一行の意味が薄まる。"},
    {"id": "b4", "pattern": "心が読める", "message_ja": "語り手はミナの外側しか知らない。他人の内心を地の文で断定しない。"}
  ],
  "notes": "地の文は常体。数字は漢数字と算用数字を混ぜず、温度は「四十二度二分」の形で統一する。時刻は「六時四十分」の形。台詞は湯ノ瀬の話し言葉（〜だべではない、〜や/〜だ）を源治に、標準語をミナとユウジに割り当てる。"
}
